insert into classes (id, name, category, type, description, "ageRange", benefits, image) values
('695f7e0e85b72085c006fb3d', 'Boxing', 'adults', 'boxing', 'Classic boxing technique and conditioning. Learn footwork, hand combinations, and defensive skills.', '16+', array['Punching technique','Hand speed','Cardio','Head movement'], 'https://i.postimg.cc/4d3fQ23b/Chat-GPT-Image-Jan-9-2026-11-03-17-AM.png'),
('695f7e0e85b72085c006fb3a', 'Adult MMA', 'adults', 'mma', 'Complete mixed martial arts for adults. Train like a fighter with proper boxing, kickboxing, wrestling, and grappling.', '16+', array['Full combat training','Fitness transformation','Stress relief','Community'], 'https://i.postimg.cc/FFVxvMRZ/Screenshot-2026-01-08-at-21-55-47.png'),
('695f7e0e85b72085c006fb3b', 'Adult Kickboxing', 'adults', 'kickboxing', 'High-intensity kickboxing classes. Perfect cardio workout combined with practical striking technique.', '16+', array['Cardio fitness','Confidence','Technique mastery','Fun workout'], 'https://i.postimg.cc/rmbkC83s/IMG-2873.jpg'),
('695f7e0e85b72085c006fb36', 'Kids Kickboxing', 'kids', 'kickboxing', 'Build strength and confidence through proper kickboxing technique. Our flagship kids program with proven results.', '7-11 years', array['Fitness improvement','Confidence boost','Discipline','Self-defense skills'], 'https://i.postimg.cc/K8p2HpLP/Screenshot-2026-01-08-at-22-08-38.png'),
('695f7e0e85b72085c006fb34', 'Tiger Tots', 'kids', 'kickboxing', 'Our youngest champions! Introduction to movement, coordination, and basic martial arts concepts in a fun, play-based environment.', '3-4 years', array['Motor skill development','Focus and attention','Confidence building','Fun group interaction'], 'https://i.postimg.cc/vBNx8tJb/Screenshot-2026-01-08-at-22-17-23.png'),
('695f7e0e85b72085c006fb35', 'Tiny Tigers', 'kids', 'kickboxing', 'Learn basic kicks, punches, and martial arts principles. Structured classes focused on discipline and respect.', '5-6 years', array['Self-confidence','Listening skills','Physical fitness','Teamwork'], 'https://i.postimg.cc/Y0DRHF37/Chat-GPT-Image-Jan-8-2026-10-13-46-PM.png'),
('695f7e0e85b72085c006fb3c', 'Adult BJJ', 'adults', 'bjj', 'Brazilian Jiu-Jitsu grappling for adults. Gi and No-Gi classes available. Perfect for all experience levels.', '16+', array['Grappling mastery','Problem solving','Functional fitness','Competition opportunities'], 'https://i.postimg.cc/N0KYy9CC/580056879-18072974534339951-8645562625290511311-n.jpg'),
('695f7e0e85b72085c006fb39', 'Teen Kickboxing', 'teens', 'kickboxing', 'Advanced kickboxing for teens. Build technique, strength, and mental toughness.', '11-15 years', array['Advanced striking','Fitness','Confidence','Stress relief'], 'https://i.postimg.cc/6Qx7yQbN/Screenshot-2026-01-08-at-22-01-56.png'),
('695f7e0e85b72085c006fb37', 'Kids BJJ', 'kids', 'bjj', 'Brazilian Jiu-Jitsu grappling classes for kids. Learn proper techniques in a safe, supportive environment.', '7-11 years', array['Grappling skills','Problem-solving','Respect for others','Coordination'], 'https://i.postimg.cc/Nfwf6n7R/Screenshot-2026-01-08-at-22-06-47.png'),
('695f7e0e85b72085c006fb3f', 'Personal Training', 'adults', 'fitness', 'One-on-one coaching tailored to your specific goals. Available for martial arts or fitness training.', '16+', array['Custom program','Intensive guidance','Fast results','Flexible scheduling'], 'https://i.postimg.cc/zGBYMHNv/IMG-5296.jpg')
insert into team_members (id, name, role, specialties, experience, bio, image) values
('695f7e1385b72085c006fb40', 'Rick Selverajah', 'Head Coach & Founder', array['MMA','Kickboxing','BJJ'], '15', 'Former competitive fighter turned coach. Passionate about developing the next generation of martial artists.', 'https://i.postimg.cc/Kvdvn5LC/websitebjj.webp'),
('695f7e1385b72085c006fb43', 'Kieran Galvin', 'Boxing Coach', array['Boxing'], '12', 'Kieran Galvin is a highly experienced boxing coach with over 12 years of training in the sport. He brings deep technical knowledge, sharp fundamentals, and a disciplined coaching style to every session. His coaching focuses on efficient movement, solid defence, and clean striking, helping students develop real boxing skill and confidence through structured, high-quality training', 'https://i.postimg.cc/2jvNvfkv/Chat-GPT-Image-Jan-9-2026-10-31-30-AM.png'),
('695f7e1385b72085c006fb41', 'Amaan Naveed', 'Senior Coach', array['Kickboxing','Kids Training','MMA','BJJ'], '4', 'Amaan is an experienced coach who''s passionate about helping people improve, no matter their starting point. He creates a welcoming, disciplined environment where members develop skill, fitness, and confidence through clear coaching and consistent progression.', 'https://i.postimg.cc/CxSDGYjM/IMG-5426.avif'),
('695f7e1385b72085c006fb42', 'Oliver Mackin', 'Senior Coach', array['Boxing','MMA','Kickboxing','Personal Training'], '3', 'Oliver Mackin is an experienced coach and personal trainer known for his clear coaching, strong fundamentals, and genuinely fun approach to training. He delivers high-quality 1-to-1 PT sessions tailored to each individual, helping members improve technique, fitness, and confidence — all while keeping sessions engaging, motivating, and enjoyable. His humour and energy create a positive environment that keeps people coming back and progressing.', 'https://i.postimg.cc/rz6GXr0w/IMG-2870.jpg')
insert into testimonials (id, name, role, content, rating, image) values
('695f7e1d85b72085c006fb49', 'Jitesh Jivram', 'Parent', 'My 11-year-old absolutely loves Revival Kickboxing! From the very first session, the coaches have been amazing — supportive, encouraging, and great with the kids. It''s not just about learning the techniques; it''s also about building confidence, respect, and discipline. The sessions are fun, well-structured, and keep the kids fully engaged. A fantastic place for children to learn and grow — both physically and mentally!', 5, 'https://i.postimg.cc/zBZXxPY5/images.png'),
('695f7e1d85b72085c006fb48', 'Reece Hughes', 'Student', 'Revival MMA has changed my life for the best, I''ve been training here for 3 years now and I''ve found a community of life long friends. The coaches are fantastic both on and off the mat. Revival has helped me find a place where I feel like I belong with how welcoming & encouraging everyone is here.', 5, 'https://i.postimg.cc/zBZXxPY5/images.png'),
('695f7e1d85b72085c006fb47', 'Deepak Lad', 'Parent', 'Revival has been amazing for my four year old. The classes are really well thought out. The coaches are brilliant with the kids, patient but firm, and you can tell they genuinely care about helping them grow in confidence and focus. It''s been great to see how much progress my child has made in such a short time. Well done Rick and team.', 5, 'https://i.postimg.cc/zBZXxPY5/images.png'),
('695f7e1d85b72085c006fb46', 'Paresh Shah', 'Parent', 'My son recently joined the kickboxing classes at Revival MMA, and we couldn''t be happier! The coaches are incredibly patient and encouraging — they strike the perfect balance between discipline and fun. My son comes home excited after every session and is already showing more confidence, focus, and fitness. The atmosphere is welcoming, and the staff really take the time to make every student feel supported. Highly recommend Revival MMA for any parent looking for a great place to help their child grow both physically and mentally!', 5, 'https://i.postimg.cc/zBZXxPY5/images.png'),
('695f7e1d85b72085c006fb4b', 'Naresh Mepani', 'Student and Parent', 'Revival MMA Kickboxing is a standout training facility with truly exceptional coaches. Their expertise, encouragement, and attention to detail make every session both challenging and rewarding. Whether you''re just starting out or refining advanced techniques, the environment is welcoming and focused. The quality of instruction and community spirit here are second to none. Highly recommended for anyone serious about improving their skills and fitness.', 5, 'https://i.postimg.cc/zBZXxPY5/images.png'),
('695f7e1d85b72085c006fb4a', 'Ankush Shukla', 'Student', 'After battling through multiple injuries and a huge hit to my confidence, I finally made the leap from regular gym training to joining Revival—and honestly, it''s one of the best decisions I''ve ever made. The difference has been life-changing. I throw myself into as many classes as possible, but the real highlight of my week is the 1-to-1 sessions with Oli. His focus on practical fight training, attention to detail, and constant care to keep me injury-free have pushed my progress further than I imagined. My form and technique have improved massively—not only thanks to Oli, but also through the incredible classes with Aman, whose leadership and energy make every session motivating.', 5, 'https://i.postimg.cc/zBZXxPY5/images.png')
