insert into faq_items (id, question, answer, category, "order") values
('696101134097cb4d946fc135', 'What age groups do you cater to?', 'We offer classes for all ages! Our Tiny Tigers program starts from age 3, we have dedicated kids classes (ages 3-10), teen programs (11-15 years), and adult classes for ages 16+. Each age group has tailored training programs designed for their development stage.', 'general', 1),
('696101134097cb4d946fc136', 'Do I need any previous experience?', 'Not at all! We welcome complete beginners as well as experienced martial artists. Our coaches are skilled at working with all levels and will help you progress at your own pace.', 'general', 2),
('696101134097cb4d946fc137', 'What should I bring to my first class?', 'Just bring comfortable workout clothes (t-shirt and shorts or joggers), a water bottle, and an open mind. We train barefoot, so no shoes needed on the mats. You can purchase any specialized equipment like gloves or shin guards from us later.', 'classes', 3),
('696101134097cb4d946fc139', 'How often should I train?', 'For beginners, we recommend starting with 2-3 classes per week to build a solid foundation. As you progress, many members train 4-5 times per week. Our coaches will help you create a training schedule that suits your goals and fitness level.', 'classes', 5),
('696101134097cb4d946fc13a', 'Is martial arts training safe for kids?', 'Absolutely! Our kids programs are designed with safety as the top priority. All our coaches are fully qualified, DBS certified, and experienced in teaching children. Classes focus on discipline, respect, and controlled techniques in a safe, supervised environment.', 'classes', 6),
('696101134097cb4d946fc13b', 'What facilities do you have?', 'As the largest martial arts academy in Harrow, we have extensive training facilities including a massive matted area with premium pro-grade mats, wall mats, and a second dedicated mat space. Our changing rooms provide everything you need for comprehensive martial arts training.', 'facilities', 7),
('696101134097cb4d946fc13c', 'Can I watch a class before joining?', 'Yes! You''re welcome to visit during our operating hours to see our facilities and watch classes in session. This is a great way to get a feel for our training environment and meet our coaches.', 'general', 8),
('696101134097cb4d946fc13d', 'Do you offer one-on-one training?', 'Yes, we offer private coaching sessions for those who want more personalized attention or have specific goals. Contact us to discuss your needs and arrange private training sessions with one of our experienced coaches.', 'classes', 9),
('696101134097cb4d946fc13e', 'What makes Revival MMA different?', 'We combine experienced, qualified coaching with a welcoming community atmosphere. Our facility is the largest in Harrow, our coaches have over 15 years of experience, and we focus on individual development while maintaining the highest standards of training. With over 450 5-star reviews on Google, our members speak for themselves!', 'general', 10)
insert into page_content (id, page, content) values
('69610623aa9282fc004a767e', 'about_video', 'https://player.vimeo.com/video/1152879712'),
('6960fee6cd92eb0b4485dd8c', 'terms', '<h2>REVIVAL MMA TERMS AND CONDITIONS</h2><h3>1. Punctuality</h3><p>It is imperative that all students attending Revival Martial arts arrive on time for each scheduled lesson, please arrive no more than 15 minutes before class.</p><h3>2. Collection of Students (KIDS)</h3><p>2.1 Parents or guardians are required to arrive promptly to collect their child before the end of each class.</p><p>2.2 The instructors of Revival Martial arts may have other commitments and cannot be responsible for students after a class is over.</p><h3>3. Acknowledgment of Responsibility</h3><p>3.1 By agreeing to these Terms and Conditions, the parent or guardian acknowledges and agrees that they are solely responsible for the student until the commencement of the lesson and the student is safely within the training space, under the supervision of the instructor. Revival MMA are not responsible for children after a class is over and students have left the mat.</p><h3>4. PAYMENT</h3><p>You agree to the following terms and conditions regarding your monthly/annual membership payments:</p><p><strong>Automatic Payment Authorisation:</strong> By initiating a Direct debit, you agree to a monthly fee being deducted on the 1st of each month at the amount agreed upon.</p><p><strong>Payment Obligations:</strong></p><ul><li>It is your responsibility to ensure that you have sufficient funds to cover the monthly/annual subscription of membership fees.</li><li>In the event of insufficient funds, it is your obligation to rectify the situation promptly to avoid any disruptions to your services.</li><li>There will be a £16.80 admin fee for any payment that has failed and needs to be resubmitted or paid via a payment link.</li></ul><h3>5. Refund policy</h3><p>Please carefully consider your membership before confirming your purchase, all sales are considered final. We do not offer refunds or exchanges for any products or services sold.</p><h3>6. Cancellation and Termination</h3><p><strong>Notice Requirement:</strong></p><ul><li>To initiate the cancellation and termination of your membership with Revival Martial Arts, you must provide a written notice clearly stating your intention to cancel your membership. You are also required to cancel the direct debit through your own banking provider. Revival Martial Arts is not responsible for cancelling any direct debit arrangements on your behalf.</li><li>The written statement must be submitted to Revival Martial arts through the designated communication channels specified by us (revivalharrow@gmail.com).</li></ul><p><strong>Continuation of Automatic Payments in Absence of Written Notice:</strong></p><ul><li>In the absence of a written statement received by Revival Martial arts regarding the cancellation and termination of your subscription, automatic payments will continue to be withdrawn from your registered account(s) as per the agreed-upon terms.</li><li>It is your responsibility to ensure the timely submission of the written cancellation notice to prevent any unintended continuation of automatic payments.</li><li>We offer the catch up class system so that any missed class can be made up at a later date, under no circumstances will a refund be given for non attendance of classes. Our direct debit company will give you monthly emails prior to your membership collection so the burden of cancelling will fall to you, not Revival MMA.</li></ul><p><strong>Confirmation of Cancellation or Payment pausing:</strong></p><ul><li>Upon receipt of your written cancellation statement, Revival Martial arts will provide confirmation of the cancellation and terminate future automatic payments accordingly.</li><li>In some cases memberships can be paused due to medical conditions, a written doctors note must be provided before monthly instalment is due for collection, please email revivalharrow@gmail.com with any documentation to request a payment pause.</li></ul><h3>7. Disobedience</h3><p>7.1 Revival Martial arts reserve the right to discontinue training for students who display persistent disobedience.</p><p>7.2 In the event a student''s behaviour becomes unmanageable and poses a detriment to the training environment and other students, the parent or guardian will be contacted. The student may be dismissed from further lessons based on the severity of their actions.</p><p>7.3 Discipline is an integral part of martial arts training, and adherence to the principles of respect and cooperation is essential for maintaining a conducive learning atmosphere.</p><h3>8. PERSONAL BELONGINGS</h3><p>8.1 Revival Martial arts cannot be held responsible for any personal belongings lost or stolen during a training session.</p><p>8.2 It is strongly advised for participants to leave valuables at home, and Revival Martial arts recommends using provided storage facilities for personal items.</p><h3>9. HEALTH AND SAFETY</h3><p>9.1 If the student has any medical conditions listed below, they must consult a doctor to ensure that intense physical exercise will not pose a problem.</p><p>9.2 The following medical conditions must be disclosed to Revival Martial arts via email before any instruction is carried out:</p><ul><li>Back problems</li><li>Any illness or injury aggravated by exercise</li><li>Head injuries</li><li>Dizziness or loss of consciousness during exercise</li><li>Joint problems aggravated by exercise, such as arthritis</li><li>Chest pains during exercise</li><li>Taking prescription medication</li><li>Heart condition</li><li>Conditions that restrict blood flow</li><li>Diabetes or other metabolic diseases</li><li>High or low blood pressure</li></ul><p>9.3 If the student has any of the listed conditions, the instructor must be informed immediately to discuss necessary actions for safety and well-being. It is advised to consult a doctor before participating to ensure it is safe.</p><p>9.4 By agreeing to these Terms and Conditions, the parent or guardian confirms that they have recently consulted a doctor who has deemed it safe for the student to participate. They further agree that they have informed the instructor or Revival Martial arts of any student medical problems and that they choose to let the student continue in this class at their own risk. They also understand that the student will be participating in a semi-contact sport involving intense physical exercise, including but not limited to running, stretching, and resistance exercise, which can result in injury or, in implausible circumstances, death.</p><p>9.5 By agreeing to these Terms and Conditions, the parent or guardian acknowledges that they have fully read and understood them and agree to all the presented terms without negotiation. These Terms and Conditions are binding and non-negotiable.</p><h3>10. EQUIPMENT PURCHASES</h3><p>10.1 All Kids equipment purchases must be made solely through Revival Martial arts. The purchase of equipment from any other suppliers or vendors is not permitted.</p><p>10.2 All adult gear MUST be purchased from us or from one of the listed brands below:</p><p><strong>APPROVED BRANDS for Kickboxing/Boxing/MMA gear:</strong></p><ul><li>TWINS</li><li>FAIRTEX</li><li>YOKKAO</li><li>SANDEE</li></ul><h3>11. GRADING GUIDELINES</h3><p><strong>Minimum Training Duration:</strong></p><p>1.1 All colour belts are required to undergo a minimum of 5 months of consistent training before submitting an application for the next belt.</p><p>1.2 Advanced belts, aspiring to ascend further, must diligently engage in 5-12 months of uninterrupted training before presenting themselves for consideration of a higher belt.</p><p>We believe that consistent and dedicated training is not only essential for individual growth but also contributes to the overall strength and skill of our martial arts community. Your commitment to these guidelines reflects your dedication to the principles of Kickboxing and ensures that you are well-prepared for the challenges and responsibilities associated with each belt level.</p><h3>12. Revival Martial arts – Video Recording Policy</h3><p>This policy is established by Revival Martial arts ("the Club") to clarify and regulate the video recording of club activities, specifically pertaining to parents recording their own child during training sessions or events. The Club recognizes the importance of capturing memorable moments for personal use but must also uphold the privacy and consent rights of all individuals involved.</p><p><strong>Policy Statement:</strong></p><p><strong>Scope:</strong> This policy applies to parents or legal guardians of Revival Martial arts members who wish to engage in video recording activities during club-related events, including training sessions, competitions, and demonstrations.</p><p><strong>Permission:</strong> Parents are permitted to record their own child during club activities for personal use only. This includes capturing moments of achievement, progress, or special events involving their child within the scope of our activities.</p><p><strong>Consent for Other Children:</strong> Parents are expressly prohibited from recording any child other than their own without explicit consent from the respective child''s parent or legal guardian. It is the responsibility of the recording parent to seek and obtain permission before capturing images or footage of other children.</p><p><strong>Requesting Consent:</strong> If a parent wishes to record moments involving other children, they must obtain explicit consent from the parent or legal guardian of each child they intend to record. This consent should be obtained in writing and presented to the Club upon request.</p><p><strong>Enforcement:</strong> The Club reserves the right to take appropriate action, including but not limited to verbal warnings, temporary suspension of recording privileges, or, in severe cases, expulsion from the Club.</p><p><strong>Compliance:</strong> All parents are expected to comply with this policy and respect the privacy of other club members. Any concerns or disputes regarding video recording should be reported to the Club''s management for resolution.</p><p>By adhering to this Video Recording Policy, Revival Martial Arts aims to create a safe and respectful environment for all members, upholding their right to privacy while allowing parents to capture and celebrate their child''s journey with us.</p><h3>13. ACADEMY RULES</h3><ul><li>No Bare feet off the mat (footwear MUST be worn when stepping off the mat)</li><li>Bow when entering and exiting the mats as a sign of respect to the training space</li><li>Always wear appropriate clothing whist training, no topless training or wearing jeans or other unsuitable attire, no items of clothing with zips or buttons</li><li>All catch up classes must be attended within the current calendar year</li><li>No parking in the Alley, we have private business who own the spaces around Revival, please keep their spaces clear at all times.</li></ul>')
